public class CharCountDemo {
    public static void main(String[] args) {
        String s = "HeLLo WoRLd 123";
        int upper = 0;    // 大写字母个数
        int lower = 0;    // 小写字母个数
        int digit = 0;    // 数字个数
        int other = 0;    // 其他字符个数

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 'A' && c <= 'Z') {
                upper++;
            } else if (c >= 'a' && c <= 'z') {
                lower++;
            } else if (c >= '0' && c <= '9') {
                digit++;
            } else {
                other++;
            }
        }

        System.out.println("大写字母：" + upper);
        System.out.println("小写字母：" + lower);
        System.out.println("数字：" + digit);
        System.out.println("其他：" + other);
    }
}
